public final class LoginPage {
  private final WebDriver driver;
  private final By user = By.name("user_name");
  private final By pass = By.name("password");
  private final By submit = By.name("sign_in");

  public LoginPage(WebDriver driver) { this.driver = driver; }

  public HomePage loginAs(String u, String p) {
    driver.findElement(user).sendKeys(u);
    driver.findElement(pass).sendKeys(p);
    driver.findElement(submit).click();
    return new HomePage(driver);
  }
}

